#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countTrapezoids(std::vector<std::vector<int>>& points) {
        std::unordered_map<int, int> y_counts;
        for (const auto& pt : points) y_counts[pt[1]]++;

        std::vector<long long> seg_counts;
        for (const auto& [y, c] : y_counts) {
            if (c >= 2) {
                seg_counts.push_back((long long)c * (c - 1) / 2);
            }
        }

        long long total = 0;
        long long running_sum = 0;
        for (long long cnt : seg_counts) {
            total += running_sum * cnt;
            running_sum += cnt;
        }

        return total;
    }
};

import java.util.*;

class Solution {
    public long countTrapezoids(int[][] points) {
        Map<Integer, Integer> yCounts = new HashMap<>();
        for (int[] pt : points) yCounts.put(pt[1], yCounts.getOrDefault(pt[1], 0) + 1);

        List<Long> segCounts = new ArrayList<>();
        for (int c : yCounts.values()) {
            if (c >= 2) {
                segCounts.add((long) c * (c - 1) / 2);
            }
        }

        long total = 0;
        long runningSum = 0;
        for (long cnt : segCounts) {
            total += runningSum * cnt;
            runningSum += cnt;
        }

        return total;
    }
}

/**
 * @param {number[][]} points
 * @return {number}
