var countTrapezoids = function(points) {
    const yCounts = new Map();
    for (const [x, y] of points) {
        yCounts.set(y, (yCounts.get(y) || 0) + 1);
    }

    const segCounts = [];
    for (const c of yCounts.values()) {
        if (c >= 2) {
            segCounts.push(Math.floor(c * (c - 1) / 2));
        }
    }

    let total = 0;
    let runningSum = 0;
    for (const cnt of segCounts) {
        total += runningSum * cnt;
        runningSum += cnt;
    }

    return total;
};
